#include <stdio.h>
int main(){
  char c; int letters=0,space=0,digit=0,other=0;
  while((c=getchar())!='\n'){
    if((c>='a'&&c<='z')||(c>='A'&&c<='Z')) letters++;
    else if(c==' ') space++;
    else if(c>='0'&&c<='9') digit++;
    else other++;
  }
  printf("letters=%d space=%d digit=%d other=%d\n",letters,space,digit,other);
  return 0;
}

#include <stdio.h>
int main(){
  long long i,n,fact=1;
  scanf("%lld",&n);
  for(i=2;i<=n;i++) fact*=i;
  printf("%lld\n",fact);
  return 0;
}

#include <stdio.h>
#include <string.h>
int main(){
  char *week[7]={"Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"};
  char s[16]; int i;
  scanf("%s",s);
  for(i=0;i<7;i++) if(strcmp(week[i],s)==0){ printf("%d\n",i); return 0; }
  printf("-1\n"); return 0;
}

#include <stdio.h>
int main(){
  int m,n,i; double sum=0;
  scanf("%d %d",&m,&n);
  for(i=m;i<=n;i++) sum += i*i + 1.0/i;
  printf("%.6f\n",sum);
  return 0;
}

#include <stdio.h>
int main(){
  int n,i,max,idx=0,a[10];
  scanf("%d",&n);
  for(i=0;i<n;i++) scanf("%d",&a[i]);
  max=a[0];
  for(i=1;i<n;i++) if(a[i]>max){ max=a[i]; idx=i; }
  printf("%d %d\n",max,idx);
  return 0;
}
